extern "C" MessageTableEntry* sChiMessageEntryTablePtr;

extern "C" MessageTableEntry* OTRMessage_GetChineseEntry(u16 textId) {
    if (sChiMessageEntryTablePtr == NULL) return NULL;
    for (MessageTableEntry* entry = sChiMessageEntryTablePtr; entry->textId != 0xFFFF; entry++) {
        if (entry->textId == textId) return entry;
    }
    return NULL;
}

extern "C" void OTRMessage_InitChinese(void) {
    sChiMessageEntryTablePtr = sChiMessageTable;
}
